"""spec render: derive source data into single human-readable view OVERVIEW.md.

Spec-0014/T3: spec render → OVERVIEW.md

Pure function, idempotent (decisions D3/D9): identical source data renders to byte-identical output twice. Generates five blocks:
  0. TL;DR top overview (Spec-0015/T4: list metadata.summary per feature, so humans see at a glance what each feature does)
  1. Global board table (group | NNNN/T* | title | status | dependencies | affected files)
  2. Cross-feature dependency graph (Mermaid, subgraph per feature; depends-on solid line, relates-to dashed line with type label)
  3. File conflict report (cross-group files overlap, collaboration signal)
  4. Per-feature section (group board + dependency DAG + evolution graph: nodes=Task versions, colored by status, lineage edges)

Decoupled from git / GitHub (principle 10).
"""

from __future__ import annotations

from pathlib import Path

from openagents.spec import model
from openagents.spec.model import Group, Task

# Spec-0014/T3: evolution graph nodes colored by status (pending/in-progress/done/abandoned).
_STATUS_FILL = {
    "pending": "#eeeeee",
    "in-progress": "#fff3b0",
    "done": "#b7e4c7",
    "abandoned": "#f4b8b8",
}

# Spec-0014/T3: fixed heading to enable assertions that "all blocks are present".
# Spec-0015/T4: TL;DR top block heading (isomorphic with _BOARD_HEADING, etc., for test assertions that blocks exist).
_TLDR_HEADING = "## Summary by feature"
_BOARD_HEADING = "## Task board"
_RELATION_HEADING = "## Cross-feature relationships"
_CONFLICT_HEADING = "## File conflict report"
_FEATURE_HEADING = "## Feature details"


def render(*, specs_root: Path) -> str:
    """Render full OVERVIEW.md text from a specs tree (pure, idempotent).

    Spec-0014/T3: pure function returns full text; empty repository returns skeleton with four block headings only, no error.
    """
    groups = model.load_all(specs_root=specs_root)
    blocks = [
        "# Specification overview (OVERVIEW)",
        "> Generated by `spec render`. Edit the source specifications, then regenerate this file.",
        # Spec-0015/T4: top human-readable overview, preceding global board.
        _render_tldr(groups=groups),
        _render_board(groups=groups),
        _render_relations(groups=groups),
        _render_conflicts(groups=groups),
        _render_features(groups=groups),
    ]
    # Join with single newline uniformly, end with newline overall to guarantee determinism.
    return "\n\n".join(blocks).rstrip("\n") + "\n"


def write_overview(*, specs_root: Path) -> Path:
    """Render and write docs/specs/OVERVIEW.md, returning its path.

    Spec-0014/T3: render + persist to specs_root/OVERVIEW.md.
    """
    path = specs_root / "OVERVIEW.md"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(render(specs_root=specs_root), encoding="utf-8")
    return path


def _render_tldr(*, groups: list[Group]) -> str:
    """Block 0: TL;DR top overview—output group-level summary per feature (Spec-0015/T4).

    Placed before global board so humans see at a glance what each feature does without first reading dense tables.
    When repository is empty, only heading remains (skeleton), no error; idempotence guaranteed by deterministic group ordering and _cell normalization.
    """
    lines = [_TLDR_HEADING]
    for group in groups:
        title = group.metadata.title or group.metadata.slug
        lines.append("")
        lines.append(f"### {group.number} {_cell(title)}")
        lines.append(_cell(group.metadata.summary))
    return "\n".join(lines)


def _render_board(*, groups: list[Group]) -> str:
    """Block 1: global board table, one row per current-version Task."""
    lines = [
        _BOARD_HEADING,
        "",
        "| Group | Task | Title | Status | Dependencies | Files |",
        "|----|----|----|----|----|----|",
    ]
    for group in groups:
        for task in group.tasks:
            qid = model.qualified_id(group=group.number, task_id=task.id)
            deps = ", ".join(task.depends_on) or "—"
            files = "<br>".join(task.files) or "—"
            lines.append(
                f"| {group.number} | {qid} | {_cell(task.title)} | {task.status} | {deps} | {files} |"
            )
    return "\n".join(lines)


def _render_relations(*, groups: list[Group]) -> str:
    """Block 2: cross-feature dependency graph (Mermaid, subgraph/feature; depends-on solid line, relates-to dashed line)."""
    lines = [_RELATION_HEADING, "", "```mermaid", "graph LR"]
    current_ids = {
        model.qualified_id(group=g.number, task_id=t.id) for g in groups for t in g.tasks
    }
    # 1. One subgraph per feature, containing its current-version Task nodes.
    for group in groups:
        lines.append(f"    subgraph G{group.number}[{group.number} {group.metadata.slug}]")
        for task in group.tasks:
            qid = model.qualified_id(group=group.number, task_id=task.id)
            lines.append(f'        {_node(qid)}["{task.id} {_cell(task.title)}"]')
        lines.append("    end")
    # 2. depends-on solid edge (parsed as qualified ID; only connects existing nodes).
    for group in groups:
        for task in group.tasks:
            src = model.qualified_id(group=group.number, task_id=task.id)
            for ref in task.depends_on:
                dst = _resolve(ref=ref, group=group.number)
                if dst in current_ids:
                    lines.append(f"    {_node(src)} --> {_node(dst)}")
    # 3. relates-to dashed edge (labeled with type).
    for group in groups:
        for task in group.tasks:
            src = model.qualified_id(group=group.number, task_id=task.id)
            for rel in task.relates_to:
                dst = _resolve(ref=rel.ref, group=group.number)
                if dst in current_ids:
                    lines.append(f"    {_node(src)} -.{rel.type}.-> {_node(dst)}")
    lines.append("```")
    return "\n".join(lines)


def _render_conflicts(*, groups: list[Group]) -> str:
    """Block 3: File conflict report — same file occupied by ≥2 groups (collaboration signal)."""
    # file -> set of group numbers occupying it.
    owners: dict[str, set[str]] = {}
    for group in groups:
        for task in group.tasks:
            for path in task.files:
                owners.setdefault(path, set()).add(group.number)

    conflicts = {path: nums for path, nums in owners.items() if len(nums) > 1}
    lines = [_CONFLICT_HEADING, ""]
    if not conflicts:
        lines.append("No cross-group file conflicts.")
        return "\n".join(lines)
    lines.extend(["| File | Groups |", "|----|----|"])
    for path, nums in sorted(conflicts.items()):
        lines.append(f"| {path} | {', '.join(sorted(nums))} |")
    return "\n".join(lines)


def _render_features(*, groups: list[Group]) -> str:
    """Block 4: per-feature section — in-group kanban + dependency DAG + evolution graph."""
    lines = [_FEATURE_HEADING]
    for group in groups:
        title = group.metadata.title or group.metadata.slug
        lines.append("")
        lines.append(f"### {group.number} {title}(issue #{group.metadata.issue})")
        lines.append("")
        lines.append(_render_group_dag(group=group))
        lines.append("")
        lines.append(_render_evolution(group=group))
    return "\n".join(lines)


def _render_group_dag(*, group: Group) -> str:
    """In-group dependency DAG (Mermaid); placeholder when no tasks."""
    lines = ["```mermaid", "graph LR"]
    ids = {task.id for task in group.tasks}
    for task in group.tasks:
        lines.append(f'    {_node(task.id)}["{task.id} {_cell(task.title)}"]')
    for task in group.tasks:
        for ref in task.depends_on:
            # In-group DAG draws only in-group dependencies (cross-group shown in global relation graph).
            if "/" not in ref and ref in ids:
                lines.append(f"    {_node(ref)} --> {_node(task.id)}")
    if not group.tasks:
        lines.append("    empty[Empty]")
    lines.append("```")
    return "\n".join(lines)


def _render_evolution(*, group: Group) -> str:
    """In-group evolution graph: node = a Task version, colored by status, edges via lineage fields."""
    lines = ["Evolution graph:", "", "```mermaid", "graph LR"]

    # 1. Aggregate each task's version sequence (historical + current), current node eases lineage edges.
    versions = _task_versions(group=group)
    used_status: set[str] = set()
    node_class: list[str] = []

    # 2. Node declaration + redefined chain between same-task versions.
    for task_id in sorted(versions):
        chain = versions[task_id]
        for snapshot in chain:
            node_id = _ver_node(task_id=task_id, version=snapshot.version)
            lines.append(f'    {node_id}["{task_id} v{snapshot.version}"]')
            used_status.add(snapshot.status)
            node_class.append(f"    class {node_id} st_{_safe(snapshot.status)};")
        for older, newer in zip(chain, chain[1:], strict=False):
            lines.append(
                f"    {_ver_node(task_id=task_id, version=older.version)} "
                f"-->|redefined| {_ver_node(task_id=task_id, version=newer.version)}"
            )

    # 3. Lineage edges (split / merged / supersedes / derived): source task latest version → this task first version.
    lines.extend(_lineage_edges(versions=versions))

    # 4. Color classDef (declare only statuses used, ensure determinism).
    for status in sorted(used_status):
        fill = _STATUS_FILL.get(status, "#ffffff")
        lines.append(f"    classDef st_{_safe(status)} fill:{fill};")
    lines.extend(node_class)
    lines.append("```")
    return "\n".join(lines)


def _task_versions(*, group: Group) -> dict[str, list[Task]]:
    """Each task_id → version sequence (historical by version number + current), for evolution graph."""
    all_ids = set(group.history) | {task.id for task in group.tasks}
    current = {task.id: task for task in group.tasks}
    result: dict[str, list[Task]] = {}
    for task_id in all_ids:
        chain = sorted(group.history.get(task_id, []), key=lambda t: t.version)
        if task_id in current:
            chain = [*chain, current[task_id]]
        result[task_id] = chain
    return result


def _lineage_edges(*, versions: dict[str, list[Task]]) -> list[str]:
    """Edge from lineage fields of latest Task version: source latest version → this task first version."""
    edges: list[str] = []
    for task_id in sorted(versions):
        chain = versions[task_id]
        if not chain:
            continue
        latest = chain[-1]
        first_node = _ver_node(task_id=task_id, version=chain[0].version)
        specs = [
            ("split", [latest.split_from] if latest.split_from else []),
            ("merged", latest.merged_from),
            ("supersedes", latest.supersedes),
            ("derived", latest.derived_from),
        ]
        for label, refs in specs:
            for ref in refs:
                # Evolution graph limited to group; extract final segment task id.
                src_id = ref.split("/")[-1]
                if src_id in versions and versions[src_id]:
                    src_node = _ver_node(task_id=src_id, version=versions[src_id][-1].version)
                    edges.append(f"    {src_node} -->|{label}| {first_node}")
    return edges


def _resolve(*, ref: str, group: str) -> str:
    """In-group shorthand → qualified ID."""
    return ref if "/" in ref else model.qualified_id(group=group, task_id=ref)


def _node(qid: str) -> str:
    """Qualified ID → valid Mermaid node name (n + non-alphanumeric to underscore)."""
    return "n" + _safe(qid)


def _ver_node(*, task_id: str, version: int) -> str:
    """Evolution graph version node name."""
    return f"v_{_safe(task_id)}_{version}"


def _safe(text: str) -> str:
    """Convert arbitrary string to Mermaid-safe identifier (non-alphanumeric → underscore)."""
    return "".join(ch if ch.isalnum() else "_" for ch in text)


def _cell(text: str) -> str:
    """Table / node label cell: compress to single line, escape pipes."""
    return text.replace("\n", " ").replace("|", "\\|").replace('"', "'")
